import '../../../core/storage/secure_token_storage.dart';import '../domain/auth_repository.dart';import '../domain/entities/auth_session.dart';import 'auth_api_datasource.dart';
class AuthRepositoryImpl implements AuthRepository{AuthRepositoryImpl(this.api,this.storage);final AuthApiDatasource api;final SecureTokenStorage storage;Future<AuthSession> _save(AuthSession s)async{await storage.saveAccessToken(s.accessToken);await storage.saveRefreshToken(s.refreshToken);return s;}Future<AuthSession> login(String p,String pw)=>api.login(p,pw).then(_save);Future<Map<String,dynamic>> register({required String name,required String phone,String? email,required String password})=>api.register({'name':name,'phone':phone,'email':email,'password':password,'password_confirmation':password});Future<AuthSession> verify(String p,String o)=>api.verify(p,o).then(_save);Future<void> logout()async{try{await api.logout();}finally{await storage.clear();}}Future<void> forgotPassword(String p)=>api.forgot(p);Future<void> resetPassword(String p,String o,String pw)=>api.reset(p,o,pw);}
